  x_in_each_loc: ['in every location', 'in jedem Ort'], x_privileges: ['Privileges (6 each)', 'Privilegien (je 6)'],
  x_influence_from: ['Rises with privileges and reforms they welcome; all influence together is always 100.', 'Steigt mit Privilegien und Reformen, die sie begrüßen; alle Einflüsse zusammen ergeben stets 100.'],
  x_content_events: ['Granting privileges, appeasing and reforms they like raise it at once; revoking and reforms they dislike lower it.', 'Privilegien, Besänftigen und genehme Reformen heben sie sofort; Entzug und ungeliebte Reformen senken sie.'],
  kh_tax: ['The crown\'s share (8 %) of what every class pays in every location: income × tax rate × control.', 'Anteil der Krone (8 %) an dem, was jeder Stand in jedem Ort zahlt: Einkommen × Steuersatz × Kontrolle.'],
  kh_trade: ['Margins of merchants trading between markets, shared by trade power: land, hub, harbours and market halls in the area, merchants, light ships and companies (the Trade panel shows each market).', 'Gewinne der Kaufleute zwischen den Märkten, verteilt nach Handelsmacht: Land, Marktort, Häfen und Markthallen im Gebiet, Kaufleute, leichte Schiffe und Kompanien (das Handelsfenster zeigt jeden Markt).'],
  kh_tariffs: ['Tolls on goods entering markets we hold, shared like trade profits.', 'Zölle auf Waren, die in unsere Märkte kommen, verteilt wie die Handelsgewinne.'],
  kh_tribute: ['Paid by subjects and realms that owe us tribute.', 'Von Untertanen und tributpflichtigen Reichen gezahlt.'], kh_contributions: ['Taxes collected in enemy land our troops occupy (half of the usual amount).', 'Steuern aus besetztem Feindesland (die Hälfte des üblichen Betrags).'],
  kh_minting: ['Extra coin from debasement: tax income × coinage rate. Raises inflation.', 'Zusätzliche Münze aus der Verschlechterung: Steuereinnahmen × Münzsatz. Erhöht die Inflation.'],
  kh_company: ['Profits of our chartered trading companies.', 'Gewinne unserer privilegierten Handelskompanien.'], kh_loans: ['Gold borrowed this month.', 'In diesem Monat geliehenes Gold.'],
  kh_army: ['Upkeep of all regiments × army maintenance; mercenaries cost 2.2 times as much; laws and doctrines change it.', 'Unterhalt aller Regimenter × Heeresunterhalt; Söldner kosten das 2,2-fache; Gesetze und Doktrinen ändern ihn.'],
  kh_navy: ['Upkeep of all ships × navy maintenance.', 'Unterhalt aller Schiffe × Flottenunterhalt.'], kh_fortresses: ['Garrisons of our fortresses: 2.5 per fort level, at most a third of our revenue.', 'Besatzungen unserer Festungen: 2,5 je Festungsstufe, höchstens ein Drittel der Einnahmen.'],
  kh_court: ['A small base, 1.2 per location and 12 % of revenue, raised by corruption.', 'Ein kleiner Grundbetrag, 1,2 je Ort und 12 % der Einnahmen, erhöht durch Korruption.'],
  kh_graft: ['A corrupt treasurer embezzles part of the taxes.', 'Ein korrupter Schatzmeister veruntreut einen Teil der Steuern.'], kh_splendour: ['A chest beyond a year\'s revenue melts away by 3 % a month, but adds prestige.', 'Ein Schatz über einem Jahreseinkommen schmilzt um 3 % im Monat, mehrt aber das Ansehen.'],
  kh_interest: ['Interest on all loans: amount × rate ÷ 12.', 'Zinsen auf alle Kredite: Betrag × Zinssatz ÷ 12.'], kh_loan_repay: ['Loans repaid this month.', 'In diesem Monat getilgte Kredite.'],
  kh_recruitment: ['New regiments and ships ordered this month.', 'In diesem Monat ausgehobene Regimenter und Schiffe.'], kh_construction: ['Buildings ordered this month.', 'In diesem Monat in Auftrag gegebene Bauten.'],
