  x_col_markets_priceIndex: ['Average price of the goods here against their anchor prices; above 1 means dear.', 'Durchschnittspreis der Waren hier gegenüber ihren Ankerpreisen; über 1 heißt teuer.'],
  x_col_markets_top: ['Goods with the largest trade value here.', 'Waren mit dem größten Handelswert hier.'],
  x_col_wars_score: ['From the attackers\' side: +100 is total victory, −100 total defeat.', 'Aus Sicht der Angreifer: +100 ist der völlige Sieg, −100 die völlige Niederlage.'],
